// Fetch school/public holidays (OpenHolidays, ODbL) and daily weather (Open-Meteo, CC BY 4.0) and build two SQL statements.
const H = this.helpers;
const get = (url) => H.httpRequest({ method: 'GET', url, json: true });
const esc = (s) => (s === null || s === undefined || s === '') ? 'NULL' : "'" + String(s).replace(/'/g, "''") + "'";
const num = (v) => (v === null || v === undefined) ? 'NULL' : String(Number(v));
const FROM = '2025-11-01';
const TO = '2027-05-31';
const countries = ['DE', 'NL', 'BE', 'DK', 'SE', 'CH', 'AT'];
const rows = [];
const topCodes = (subs) => [...new Set((subs || []).map(s => s.code).filter(c => /^[A-Z]{2}-[A-Z0-9]{1,3}$/.test(c)))];
for (const c of countries) {
  for (const kind of ['School', 'Public']) {
    let list = [];
    try {
      list = await get('https://openholidaysapi.org/' + kind + 'Holidays?countryIsoCode=' + c + '&languageIsoCode=EN&validFrom=' + FROM + '&validTo=' + TO);
    } catch (e) { list = []; }
    for (const h of list) {
      const name = ((h.name || []).find(n => n.language === 'EN') || (h.name || [])[0] || {}).text || kind;
      const type = kind.toLowerCase() + ': ' + name;
      const codes = topCodes(h.subdivisions);
      if (c === 'DE' && codes.length) {
        for (const code of codes) rows.push([c, code, h.startDate, h.endDate, type]);
      } else {
        const region = codes.length ? codes.map(x => x.split('-')[1]).join(',') : null;
        rows.push([c, region, h.startDate, h.endDate, type]);
      }
    }
  }
}
// Easter Sunday (Gregorian computus) for 2025-2027
for (const y of [2025, 2026, 2027]) {
  const a = y % 19, b = Math.floor(y / 100), cc = y % 100, d = Math.floor(b / 4), e = b % 4;
  const f = Math.floor((b + 8) / 25), g = Math.floor((b - f + 1) / 3);
  const hh = (19 * a + b - d - g + 15) % 30, i = Math.floor(cc / 4), k = cc % 4;
  const l = (32 + 2 * e + 2 * i - hh - k) % 7, m = Math.floor((a + 11 * hh + 22 * l) / 451);
  const month = Math.floor((hh + l - 7 * m + 114) / 31), day = ((hh + l - 7 * m + 114) % 31) + 1;
  const iso = y + '-' + String(month).padStart(2, '0') + '-' + String(day).padStart(2, '0');
  rows.push(['AT', null, iso, iso, 'easter: Easter Sunday']);
}
// UK school holidays (England, approximate, hardcoded)
const uk = [
  ['2025-12-20', '2026-01-04', 'school: Christmas'], ['2026-02-16', '2026-02-22', 'school: February half term'],
  ['2026-03-28', '2026-04-12', 'school: Easter'], ['2026-12-19', '2027-01-03', 'school: Christmas'],
  ['2027-02-15', '2027-02-21', 'school: February half term'], ['2027-03-27', '2027-04-11', 'school: Easter']
];
for (const u of uk) rows.push(['UK', 'England', u[0], u[1], u[2] + ' (hardcoded, approximate)']);

// Weather: Ischgl, archive API lags about 2 days
const end = new Date(Date.now() - 3 * 86400000).toISOString().slice(0, 10);
const w = await get('https://archive-api.open-meteo.com/v1/archive?latitude=46.97&longitude=10.29&start_date=2025-11-04&end_date=' + end + '&daily=temperature_2m_max,temperature_2m_min,precipitation_sum,snowfall_sum&timezone=Europe%2FBerlin');
const dly = w.daily;
const wrows = dly.time.map((t, i) => [t, 'Ischgl', dly.temperature_2m_max[i], dly.temperature_2m_min[i], dly.precipitation_sum[i], dly.snowfall_sum[i]]);

const hv = rows.map(r => '(' + [esc(r[0]), esc(r[1]), esc(r[2]) + '::date', esc(r[3]) + '::date', esc(r[4])].join(',') + ')').join(',');
const wv = wrows.map(r => '(' + [esc(r[0]) + '::date', esc(r[1]), num(r[2]), num(r[3]), num(r[4]), num(r[5])].join(',') + ')').join(',');
const sql_h = 'with d as (delete from public.team_07_holidays returning 1) insert into public.team_07_holidays (market, region, start_date, end_date, type) values ' + hv;
const sql_w = 'with d as (delete from public.team_07_weather_daily returning 1) insert into public.team_07_weather_daily (date, location, temp_max, temp_min, precip_mm, snowfall_cm) values ' + wv;
return [{ json: { sql_h, sql_w, counts: { holidays: rows.length, weather_days: wrows.length, weather_until: end } } }];
